export function dayKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
export function cleanProgress(raw={}){const known=new Set(QUESTS.map(q=>q.id));return {unlocked:[...new Set((Array.isArray(raw.unlocked)?raw.unlocked:[]).filter(id=>['collector','researcher','taskmaster','evidence','voice','safety','planner','streak'].includes(id)))],claims:[...new Set((Array.isArray(raw.claims)?raw.claims:[]).filter(id=>known.has(id)||/^daily:\d{4}-\d{2}-\d{2}$/.test(id)))].slice(0,500),quizPassed:raw.quizPassed===true,days:[...new Set((Array.isArray(raw.days)?raw.days:[]).filter(d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)))].sort().slice(-365)}}
export function xpTotal(progress){return cleanProgress(progress).claims.reduce((n,id)=>n+(id.startsWith('daily:')?15:QUESTS.find(q=>q.id===id)?.xp||0),0)}
export function levelInfo(xp){const level=Math.floor(Math.sqrt(Math.max(0,xp)/100))+1,start=100*(level-1)**2,next=100*level**2;return {level,start,next,percent:(xp-start)/(next-start)*100,title:level>=5?'Curator':level>=3?'Researcher':level>=2?'Explorer':'Newcomer'}}
export function streak(progress,now=new Date()){const days=new Set(cleanProgress(progress).days),date=new Date(now.getFullYear(),now.getMonth(),now.getDate());if(!days.has(dayKey(date)))date.setDate(date.getDate()-1);let n=0;while(days.has(dayKey(date))){n++;date.setDate(date.getDate()-1)}return n}
export function claimQuest(state,id,now=new Date()){const progress=cleanProgress(state.progress);if(progress.claims.includes(id))throw Error('XP misi ini sudah diklaim.');if(id===`daily:${dayKey(now)}`){if(!progress.days.includes(dayKey(now)))throw Error('Selesaikan aktivitas riset atau pelajaran hari ini.')}else{const q=QUESTS.find(q=>q.id===id);if(!q||q.count({...state,progress})<q.target)throw Error('Syarat misi belum selesai.')}return {...progress,claims:[...progress.claims,id]}}
