export function badgeEarned(b,state){return cleanProgress(state.progress).unlocked.includes(b.id)||b.count(state)>=b.target}
export function unlockBadges(state){const progress=cleanProgress(state.progress);return {...progress,unlocked:[...new Set([...progress.unlocked,...BADGES.filter(b=>b.count(state)>=b.target).map(b=>b.id)])]}}
